import click


class CustomShell(ShellComplete):
    name = "custom"
    def source(self):
        return "source"

    def format_completion(self, item):
        return item.value


def test_chained_mutation_kill():
    """Test that chained completion items are handled correctly."""
    @click.group()
    def cli():
        pass

    @cli.group()
    def sub():
        pass

    @sub.command()
    def cmd():
        pass

    # Create a shell completion instance that uses the chained logic
    shell = CustomShell(cli, {}, "cli", ["sub", "cmd"])

    # Get completions for the chained command - args should be a list
    completions = shell.get_completions(["sub", "cmd"], "cmd")

    # The key behavior: when completing a chained command, 
    # the completion should include the command itself as a completion item
    # This tests the logic around line 536 which handles chained command completion
    # For a chained command, the completion should suggest the subcommand's options
    # or the next command in the chain
    assert len(completions) > 0

    # Verify the completion items have proper values
    for item in completions:
        assert item.value is not None
        assert isinstance(item.value, str)

