import pytest
from jinja2 import Environment
from jinja2.nodes import Template

def test_mutation_kill_866():
    env = Environment()
    # Test that namespace attribute assignment inside a for loop
    # correctly accumulates values across iterations
    source = """
    {% set ns = namespace(total=0) %}
    {% for i in [1, 2, 3] %}
        {% set ns.total = ns.total + i %}
    {% endfor %}
    {{ ns.total }}
    """
    template = env.from_string(source)
    result = template.render()
    assert result.strip() == "6"
